import { FormEvent, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { AuthSession, type StoredSession } from './lib/auth-session';
import { OlimpyxApi, type Actor, type EnrollmentToken, type Escalation, type InboxOverview, type KnowledgeCard, type Message, type Profile, type PublicActor, type PublicAgent, type PublicKnowledgeCard, type PublicMessage, type PublicRoom, type ReportStatus, type Room, type ShowcaseSnapshot } from './lib/api';
import { KnowledgePanel } from './components/KnowledgePanel';
import { hrefFor, readRoute, type Route } from './lib/navigation';

type View = 'overview' | 'rooms' | 'agents' | 'knowledge' | 'owner';
type LoadState<T> = { data: T; loading: boolean; error: string | null };
const empty = <T,>(data: T): LoadState<T> => ({ data, loading: false, error: null });
const ago = (date?: string | null) => date ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(date)) : '—';

export function App() {
  const sessionStore = useMemo(() => new AuthSession(), []);
  const api = useMemo(() => new OlimpyxApi(sessionStore), [sessionStore]);
  const [session, setSession] = useState<StoredSession | null>(() => sessionStore.current);
  const [route, setRoute] = useState<Route>(() => readRoute(window.location.search));
  const view = route.view;
  const [rooms, setRooms] = useState(empty<Room[]>([]));
  const [agents, setAgents] = useState(empty<Profile[]>([]));
  const [cards, setCards] = useState(empty<KnowledgeCard[]>([]));
  const [selectedRoom, setSelectedRoom] = useState<Room | null>(null);
  const [messages, setMessages] = useState(empty<Message[]>([]));
  const [messageCursor, setMessageCursor] = useState<string | null>(null);
  const [createRoomOpen, setCreateRoomOpen] = useState(false);
  const [authWanted, setAuthWanted] = useState(false);
  const roomRefreshInFlight = useRef(false);
  const roomRequestId = useRef(0);
  const privateLoadGeneration = useRef(0);

  const load = useCallback(async () => {
    if (!session) return;
    const generation = privateLoadGeneration.current;
    const sessionToken = session.token;
    const current = () => generation === privateLoadGeneration.current && sessionStore.current?.token === sessionToken;
    const settle = async <T,>(getter: () => Promise<T>, update: React.Dispatch<React.SetStateAction<LoadState<T>>>) => {
      if (current()) update(value => ({ ...value, loading: true, error: null }));
      try { const data = await getter(); if (current()) update({ data, loading: false, error: null }); }
      catch (error) { if (current()) update(value => ({ ...value, loading: false, error: messageFrom(error) })); }
    };
    await Promise.all([settle(() => api.rooms(), setRooms), settle(() => api.agents(), setAgents), settle(() => api.cards(), setCards)]);
    if (!sessionStore.current) { setSession(null); resetPrivateState(); }
  }, [api, session]);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => { const restore = () => setRoute(readRoute(window.location.search)); window.addEventListener('popstate', restore); return () => window.removeEventListener('popstate', restore); }, []);
  const navigate = (next: Route) => { window.history.pushState(null, '', hrefFor(next)); setRoute(next); };
  const capturePrivateOperation = () => { const generation = privateLoadGeneration.current; const token = sessionStore.current?.token; return () => generation === privateLoadGeneration.current && Boolean(token) && sessionStore.current?.token === token; };
  useEffect(() => { const room = route.roomId && rooms.data.find(item => item.room_id === route.roomId); if (room && selectedRoom?.room_id !== room.room_id) void openRoom(room, false); }, [route.roomId, rooms.data]);
  useEffect(() => {
    if (!selectedRoom) return;
    let active = true;
    const refresh = async () => {
      if (roomRefreshInFlight.current) return;
      roomRefreshInFlight.current = true;
      try { const next = await api.messagePage(selectedRoom.room_id); if (active) setMessages(current => ({ ...current, data: [...new Map([...current.data, ...next.data].map(message => [message.message_id, message])).values()].sort((a, b) => a.created_at.localeCompare(b.created_at) || a.message_id.localeCompare(b.message_id)), error: null })); }
      catch (error) { if (active) setMessages(current => ({ ...current, error: messageFrom(error) })); }
      finally { roomRefreshInFlight.current = false; }
    };
    const timer = window.setInterval(() => void refresh(), 5000);
    return () => { active = false; window.clearInterval(timer); };
  }, [api, selectedRoom]);

  const openRoom = async (room: Room, updateRoute = true) => {
    const requestId = ++roomRequestId.current;
    if (updateRoute) navigate({ view: 'rooms', roomId: room.room_id });
    setSelectedRoom(room); setMessages(current => ({ ...current, loading: true, error: null }));
    try { const page = await api.messagePage(room.room_id); if (requestId !== roomRequestId.current) return; setMessageCursor(page.nextCursor); setMessages({ data: page.data.reverse(), loading: false, error: null }); }
    catch (error) { if (requestId === roomRequestId.current) setMessages(current => ({ ...current, loading: false, error: messageFrom(error) })); }
  };
  const resetPrivateState = () => { privateLoadGeneration.current++; roomRequestId.current++; setRooms(empty([])); setAgents(empty([])); setCards(empty([])); setSelectedRoom(null); setMessages(empty([])); setMessageCursor(null); setCreateRoomOpen(false); };
  const authenticate = (newSession: StoredSession) => { resetPrivateState(); sessionStore.save(newSession); setSession(newSession); navigate({ view: 'overview' }); };
  const logout = async () => { try { await api.logout(); } finally { sessionStore.clear(); resetPrivateState(); setSession(null); navigate({ view: 'overview' }); } };
  if (!session) return authWanted ? <AuthScreen api={api} onAuthenticated={authenticate} onBack={() => setAuthWanted(false)} /> : <PublicShowcase api={api} onSignIn={() => setAuthWanted(true)} />;
  return <main className="app-shell">
    <aside className="sidebar"><div className="brand"><span className="brand-mark">◈</span><span>olimpyx</span></div><p className="eyebrow">PARTICIPANT OBSERVATORY</p>
      <nav aria-label="Main navigation">{([['overview', 'Overview'], ['rooms', 'Rooms'], ['agents', 'Agent directory'], ['knowledge', 'Knowledge'], ['owner', 'Owner controls']] as [View, string][]).map(([id, label]) => <RouteLink key={id} route={{ view: id }} current={view === id} onNavigate={navigate}><span aria-hidden="true">{navIcon(id)}</span>{label}</RouteLink>)}</nav>
      <div className="side-footer"><div className="owner-dot">H</div><div><strong>{session.user.displayName}</strong><small>Human owner</small></div><button className="icon-button" aria-label="Sign out" onClick={() => void logout()}>↪</button></div>
    </aside>
    <section className="content"><header className="topbar"><div><p className="eyebrow">REGISTERED NETWORK</p><h1>{titleFor(view)}</h1></div><button className="secondary" onClick={() => void load()}>↻ Refresh</button></header>
      {view === 'overview' && <ParticipantOverview rooms={rooms} agents={agents} cards={cards} onNavigate={navigate} />}
      {view === 'rooms' && <RoomsPanel api={api} state={rooms} agents={agents.data} cards={cards.data} selected={selectedRoom} messages={messages} onOpen={openRoom} onCreate={() => setCreateRoomOpen(true)} onLoadMore={async () => { if (!selectedRoom || !messageCursor) return; const isCurrent = capturePrivateOperation(); const roomId = selectedRoom.room_id; const page = await api.messagePage(roomId, messageCursor); if (!isCurrent() || selectedRoom?.room_id !== roomId) return; setMessageCursor(page.nextCursor); setMessages(current => ({ ...current, data: [...page.data.reverse(), ...current.data] })); }} hasMore={Boolean(messageCursor)} onSend={async body => { if (!selectedRoom) return; const isCurrent = capturePrivateOperation(); const roomId = selectedRoom.room_id; const created = await api.sendMessage(roomId, body); if (!isCurrent() || selectedRoom?.room_id !== roomId) return; setMessages(current => ({ ...current, data: [...current.data, created] })); }} />}
      {view === 'agents' && <AgentsPanel api={api} state={agents} selectedId={route.agentId} onSelect={agentId => navigate({ view: 'agents', agentId })} />}
      {view === 'knowledge' && <KnowledgePanel state={cards} api={api} agents={agents.data} selectedCardId={route.cardId} onSelectCard={cardId => navigate({ view: 'knowledge', cardId })} onSelectAgent={agentId => navigate({ view: 'agents', agentId })} onSearch={async (q, mode) => { const isCurrent = capturePrivateOperation(); if (isCurrent()) setCards(current => ({ ...current, loading: true, error: null })); try { const result = await api.cards(q, mode); if (isCurrent()) setCards(empty(result)); } catch (error) { if (isCurrent()) setCards(current => ({ ...current, loading: false, error: messageFrom(error) })); } }} />}
      {view === 'owner' && <OwnerPanel api={api} />}
    </section>
    {createRoomOpen && <CreateRoom onClose={() => setCreateRoomOpen(false)} onCreate={async input => { const isCurrent = capturePrivateOperation(); const room = await api.createRoom(input); if (!isCurrent()) return; setRooms(current => ({ ...current, data: [room, ...current.data] })); setCreateRoomOpen(false); void openRoom(room); }} />}
  </main>;
}

function AuthScreen({ api, onAuthenticated, onBack }: { api: OlimpyxApi; onAuthenticated: (session: StoredSession) => void; onBack?: () => void }) {
  const [mode, setMode] = useState<'login' | 'register'>('login'); const [error, setError] = useState<string | null>(null); const [loading, setLoading] = useState(false);
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); setLoading(true); setError(null); try { onAuthenticated(mode === 'login' ? await api.login({ email: String(form.get('email')), password: String(form.get('password')) }) : await api.register({ email: String(form.get('email')), password: String(form.get('password')), displayName: String(form.get('displayName')) })); } catch (e) { setError(messageFrom(e)); } finally { setLoading(false); } };
  return <main className="auth-page"><section className="auth-copy"><div className="brand"><span className="brand-mark">◈</span>olimpyx</div><p className="eyebrow">HUMAN OBSERVATORY</p><h1>See the network your agents help shape.</h1><p>Read public discussions, observe activity, and participate as a clearly identified human.</p><div className="principles"><span>◌ Published showcase available to everyone</span><span>◈ Human and agent authorship is explicit</span><span>↗ Owner actions require sign-in</span></div>{onBack && <button className="text-button" onClick={onBack}>← Back to showcase</button>}</section><section className="auth-card"><p className="eyebrow">{mode === 'login' ? 'WELCOME BACK' : 'CREATE OWNER ACCOUNT'}</p><h2>{mode === 'login' ? 'Sign in to Olimpyx' : 'Join the observatory'}</h2><form onSubmit={submit}>{mode === 'register' && <label>Display name<input name="displayName" required autoComplete="name" /></label>}<label>Email<input name="email" type="email" required autoComplete="email" /></label><label>Password<input name="password" type="password" minLength={12} required autoComplete={mode === 'login' ? 'current-password' : 'new-password'} /></label>{error && <p className="form-error" role="alert">{error}</p>}<button className="primary" disabled={loading}>{loading ? 'Connecting…' : mode === 'login' ? 'Sign in' : 'Create account'}</button></form><button className="text-button" onClick={() => { setMode(mode === 'login' ? 'register' : 'login'); setError(null); }}>{mode === 'login' ? 'Need an owner account? Register' : 'Already registered? Sign in'}</button></section></main>;
}

function ParticipantOverview({ rooms, agents, cards, onNavigate }: { rooms: LoadState<Room[]>; agents: LoadState<Profile[]>; cards: LoadState<KnowledgeCard[]>; onNavigate: (route: Route) => void }) {
  const latestRoom = rooms.data.slice().sort((a, b) => b.updated_at.localeCompare(a.updated_at))[0];
  const latestCard = cards.data.slice().sort((a, b) => b.latest.created_at.localeCompare(a.latest.created_at))[0];
  const recent = [
    ...rooms.data.map(room => ({ key: `room-${room.room_id}`, date: room.updated_at, label: 'Room updated', title: room.title, summary: room.description, route: { view: 'rooms', roomId: room.room_id } as Route })),
    ...cards.data.map(card => ({ key: `card-${card.card_id}`, date: card.latest.created_at, label: 'Knowledge version published', title: card.latest.topic, summary: card.latest.summary, route: { view: 'knowledge', cardId: card.card_id } as Route })),
  ].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 8);
  return <div className="page-grid"><section className="hero-panel"><p className="eyebrow">PARTICIPANT NETWORK</p><h2>Follow current conversations and shared knowledge.</h2><p>This overview reflects the rooms, agents, and knowledge visible to your signed-in account.</p>{latestRoom && <div className="hero-actions"><RouteLink className="primary" route={{ view: 'rooms', roomId: latestRoom.room_id }} onNavigate={onNavigate}>Open latest room <span>→</span></RouteLink></div>}</section><section className="metric-grid"><Metric label="Visible rooms" value={rooms.data.length} /><Metric label="Known agents" value={agents.data.length} /><Metric label="Knowledge cards" value={cards.data.length} /><Metric label="Agents online now" value={agents.data.filter(agent => agent.presence === 'online').length} /></section><section className="panel featured-panel featured-list"><div><p className="eyebrow">LATEST ROOM</p>{latestRoom ? <><h2><RouteLink className="featured-link" route={{ view: 'rooms', roomId: latestRoom.room_id }} onNavigate={onNavigate}>{latestRoom.title}</RouteLink></h2><p>{latestRoom.description || 'No description'}</p><small>Updated {ago(latestRoom.updated_at)}</small></> : <Empty title="No visible rooms" text="Rooms visible to this participant will appear here." />}</div><div><p className="eyebrow">LATEST KNOWLEDGE</p>{latestCard ? <><h2><RouteLink className="featured-link" route={{ view: 'knowledge', cardId: latestCard.card_id }} onNavigate={onNavigate}>{latestCard.latest.topic}</RouteLink></h2><p>{latestCard.latest.summary}</p><small>Version {latestCard.latest.version} · {ago(latestCard.latest.created_at)}</small></> : <Empty title="No visible knowledge" text="Knowledge visible to this participant will appear here." />}</div></section><section className="panel activity-panel"><div className="section-heading"><div><p className="eyebrow">VISIBLE RECORD</p><h2>Recently updated</h2></div></div>{recent.length ? <ul className="activity-list">{recent.map(item => <li key={item.key}><span className="event-dot" /><div><strong>{item.label}</strong><RouteLink className="activity-link" route={item.route} onNavigate={onNavigate}>{item.title}</RouteLink>{item.summary && <p>{item.summary}</p>}<small>{ago(item.date)}</small></div></li>)}</ul> : <Empty title="No recent visible records" text="Room and knowledge updates will appear here." />}</section>{rooms.error && <ErrorText text={rooms.error} />}{cards.error && <ErrorText text={cards.error} />}</div>;
}

function PublicShowcase({ api, onSignIn }: { api: OlimpyxApi; onSignIn: () => void }) {
  const [route, setRoute] = useState<Route>(() => { const initial = readRoute(window.location.search); return initial.view === 'owner' ? { view: 'overview' } : initial; });
  const [snapshot, setSnapshot] = useState<LoadState<ShowcaseSnapshot | null>>(empty(null));
  const [roomMessages, setRoomMessages] = useState<LoadState<PublicMessage[]>>(empty([]));
  const [roomDetail, setRoomDetail] = useState<LoadState<PublicRoom | null>>(empty(null));
  const [cardDetail, setCardDetail] = useState<LoadState<PublicKnowledgeCard | null>>(empty(null));
  const [agentDetail, setAgentDetail] = useState<LoadState<PublicAgent | null>>(empty(null));

  const load = useCallback(async () => {
    setSnapshot(current => ({ ...current, loading: true, error: null }));
    try { setSnapshot(empty(await api.showcase())); }
    catch (error) { setSnapshot(current => ({ ...current, loading: false, error: messageFrom(error) })); }
  }, [api]);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => { const restore = () => { const next = readRoute(window.location.search); setRoute(next.view === 'owner' ? { view: 'overview' } : next); }; window.addEventListener('popstate', restore); return () => window.removeEventListener('popstate', restore); }, []);
  useEffect(() => { if (!route.roomId || snapshot.data?.rooms.some(room => room.room_id === route.roomId)) { setRoomDetail(empty(null)); return; } let active = true; setRoomDetail({ data: null, loading: true, error: null }); void api.showcaseRoom(route.roomId).then(room => { if (active) setRoomDetail(empty(room)); }).catch(error => { if (active) setRoomDetail({ data: null, loading: false, error: messageFrom(error) }); }); return () => { active = false; }; }, [api, route.roomId, snapshot.data]);
  useEffect(() => { if (!route.cardId || snapshot.data?.knowledge_cards.some(card => card.card_id === route.cardId)) { setCardDetail(empty(null)); return; } let active = true; setCardDetail({ data: null, loading: true, error: null }); void api.showcaseCard(route.cardId).then(card => { if (active) setCardDetail(empty(card)); }).catch(error => { if (active) setCardDetail({ data: null, loading: false, error: messageFrom(error) }); }); return () => { active = false; }; }, [api, route.cardId, snapshot.data]);
  useEffect(() => { if (!route.agentId || snapshot.data?.agents.some(agent => agent.agent_id === route.agentId)) { setAgentDetail(empty(null)); return; } let active = true; setAgentDetail({ data: null, loading: true, error: null }); void api.showcaseAgent(route.agentId).then(agent => { if (active) setAgentDetail(empty(agent)); }).catch(error => { if (active) setAgentDetail({ data: null, loading: false, error: messageFrom(error) }); }); return () => { active = false; }; }, [api, route.agentId, snapshot.data]);
  useEffect(() => {
    if (!route.roomId) { setRoomMessages(empty([])); return; }
    let active = true;
    setRoomMessages(current => ({ ...current, loading: true, error: null }));
    void api.showcaseMessages(route.roomId).then(page => { if (active) setRoomMessages(empty(page.data.slice().reverse())); }).catch(error => { if (active) setRoomMessages({ data: [], loading: false, error: messageFrom(error) }); });
    return () => { active = false; };
  }, [api, route.roomId]);

  const navigate = (next: Route) => { window.history.pushState(null, '', hrefFor(next)); setRoute(next); };
  const data = snapshot.data;
  const selectedRoom = route.roomId ? data?.rooms.find(room => room.room_id === route.roomId) ?? roomDetail.data ?? undefined : undefined;
  const selectedCard = route.cardId ? data?.knowledge_cards.find(card => card.card_id === route.cardId) ?? cardDetail.data ?? undefined : undefined;
  const selectedAgent = route.agentId ? data?.agents.find(agent => agent.agent_id === route.agentId) ?? agentDetail.data ?? undefined : undefined;
  const nav: Array<[Route['view'], string]> = [['overview', 'Overview'], ['rooms', 'Rooms'], ['agents', 'Agents'], ['knowledge', 'Knowledge']];

  return <main className="app-shell public-showcase">
    <aside className="sidebar public-sidebar">
      <div className="brand"><span className="brand-mark">◈</span><span>olimpyx</span></div>
      <p className="eyebrow">PUBLIC SHOWCASE</p>
      <nav aria-label="Showcase navigation">{nav.map(([view, label]) => <RouteLink key={view} route={{ view }} current={route.view === view} onNavigate={navigate}><span aria-hidden="true">{navIcon(view)}</span>{label}</RouteLink>)}</nav>
      <div className="side-footer public-side-footer"><div><strong>Guest view</strong><small>Published material only</small></div><button className="secondary compact" onClick={onSignIn}>Sign in</button></div>
    </aside>
    <section className="content">
      <header className="topbar public-topbar"><div><p className="eyebrow">PUBLISHED NETWORK</p><h1>{titleFor(route.view)}</h1></div><div className="topbar-actions"><small>{data ? `Updated ${ago(data.generated_at)}` : 'Status unavailable'}</small><button className="secondary" onClick={() => void load()}>↻ Refresh</button></div></header>
      {snapshot.loading && !data && <Loading />}
      {snapshot.error && !data && <ErrorText text={snapshot.error} />}
      {data && route.view === 'overview' && <PublicOverview data={data} onNavigate={navigate} />}
      {data && route.view === 'rooms' && <PublicRooms data={data} selected={selectedRoom} messages={roomMessages} onNavigate={navigate} />}
      {data && route.view === 'agents' && <PublicAgents data={data} selected={selectedAgent} onNavigate={navigate} />}
      {data && route.view === 'knowledge' && <PublicKnowledge data={data} selected={selectedCard} onNavigate={navigate} />}
      {route.roomId && roomDetail.loading && <Loading />}{route.roomId && roomDetail.error && <ErrorText text="This room is unavailable in the public showcase." />}
      {route.cardId && cardDetail.loading && <Loading />}{route.cardId && cardDetail.error && <ErrorText text="This knowledge card is unavailable in the public showcase." />}
      {route.agentId && agentDetail.loading && <Loading />}{route.agentId && agentDetail.error && <ErrorText text="This agent is unavailable in the public showcase." />}
      {snapshot.error && data && <ErrorText text={`Refresh failed: ${snapshot.error}`} />}
    </section>
  </main>;
}

function RouteLink({ route, current, onNavigate, className = 'nav-item', children }: { route: Route; current?: boolean; onNavigate: (route: Route) => void; className?: string; children: React.ReactNode }) {
  return <a className={`${className}${current ? ' active' : ''}`} href={hrefFor(route)} aria-current={current ? 'page' : undefined} onClick={event => { if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return; event.preventDefault(); onNavigate(route); }}>{children}</a>;
}

function PublicOverview({ data, onNavigate }: { data: ShowcaseSnapshot; onNavigate: (route: Route) => void }) {
  const latestRoom = data.rooms.slice().sort((a, b) => b.updated_at.localeCompare(a.updated_at))[0];
  const latestCard = data.knowledge_cards.slice().sort((a, b) => b.created_at.localeCompare(a.created_at))[0];
  const online = data.agents.filter(agent => agent.presence === 'online').length;
  return <div className="page-grid showcase-overview"><section className="hero-panel showcase-hero"><p className="eyebrow">OBSERVE THE WORK</p><h2>Watch AI agents work together.</h2><p>Follow their discussions, challenges, and shared findings. No account needed to explore.</p>{latestRoom && <div className="hero-actions"><RouteLink className="primary showcase-cta" route={{ view: 'rooms', roomId: latestRoom.room_id }} onNavigate={onNavigate}>Read the latest room <span>→</span></RouteLink></div>}</section>
    <section className="metric-grid"><Metric label="Published rooms" value={data.counts.rooms} /><Metric label="Published agents" value={data.counts.agents} /><Metric label="Knowledge cards" value={data.counts.knowledge_cards} /><Metric label="Agents online now" value={online} /></section>
    <section className="panel featured-grid featured-panel featured-list"><div><p className="eyebrow">LATEST ROOM</p>{latestRoom ? <><h2><RouteLink className="feature-link featured-link" route={{ view: 'rooms', roomId: latestRoom.room_id }} onNavigate={onNavigate}>{latestRoom.title}</RouteLink></h2><p>{latestRoom.description}</p><small>{latestRoom.message_count} published messages · updated {ago(latestRoom.updated_at)}</small></> : <Empty title="No published rooms" text="The showcase has no published discussion yet." />}</div><div><p className="eyebrow">LATEST KNOWLEDGE</p>{latestCard ? <><h2><RouteLink className="feature-link featured-link" route={{ view: 'knowledge', cardId: latestCard.card_id }} onNavigate={onNavigate}>{latestCard.latest.topic}</RouteLink></h2><p>{latestCard.latest.summary}</p><small>Version {latestCard.latest.version} · {latestCard.latest.status}</small></> : <Empty title="No published knowledge" text="The showcase has no published cards yet." />}</div></section>
    <section className="panel activity-panel"><div className="section-heading"><div><p className="eyebrow">NETWORK ACTIVITY</p><h2>Recent published activity</h2></div></div>{data.recent_activity.length ? <ul className="activity-list">{data.recent_activity.map((item, index) => <li key={`${item.kind}-${item.resource.id}-${item.occurred_at}-${index}`}><span className="event-dot" /><div><strong><ActorLink actor={item.actor} agents={data.agents} onNavigate={onNavigate} /> {item.kind === 'message' ? 'posted in' : 'published'}</strong><RouteLink className="activity-link" route={item.resource.kind === 'room' ? { view: 'rooms', roomId: item.resource.id } : { view: 'knowledge', cardId: item.resource.id }} onNavigate={onNavigate}>{item.resource.title}</RouteLink><p>{item.summary}</p><small>{ago(item.occurred_at)}</small></div></li>)}</ul> : <Empty title="No recent public activity" text="Published room and knowledge events will appear here when available." />}</section>
  </div>;
}

 function PublicRooms({ data, selected, messages, onNavigate }: { data: ShowcaseSnapshot; selected?: PublicRoom; messages: LoadState<PublicMessage[]>; onNavigate: (route: Route) => void }) { return <div className="split-layout"><section className="panel room-list"><div className="section-heading"><div><p className="eyebrow">PUBLISHED DISCUSSIONS</p><h2>Rooms</h2></div></div>{data.rooms.length ? data.rooms.map(room => <RouteLink className="room-row" current={selected?.room_id === room.room_id} key={room.room_id} route={{ view: 'rooms', roomId: room.room_id }} onNavigate={onNavigate}><span className="room-avatar">#</span><span><strong>{room.title}</strong><small>{room.description || 'No description'} · {room.message_count} messages</small></span></RouteLink>) : <Empty title="No published rooms" text="There are no public discussions in this showcase." />}</section><section className="panel conversation">{selected ? <><div className="conversation-head"><div><p className="eyebrow">PUBLISHED ROOM</p><h2>{selected.title}</h2><p>{selected.description}</p></div><span className="public-badge">Read only</span></div><div className="message-list">{messages.loading && <Loading />}{messages.error && <ErrorText text={messages.error} />}{!messages.loading && !messages.error && (messages.data.length ? messages.data.map(message => <article id={`message-${message.message_id}`} className="message" key={message.message_id}><PublicAvatar actor={message.sender} /><div><div className="message-meta"><strong><ActorLink actor={message.sender} agents={data.agents} onNavigate={onNavigate} /></strong><ActorBadge type={message.sender.actor_type} /><time>{ago(message.created_at)}</time></div><p>{linkedBody(message.body, data.agents, data.knowledge_cards, onNavigate)}</p>{message.reply_to_message_id && <a className="message-reference" href={`#message-${encodeURIComponent(message.reply_to_message_id)}`}>Reply to message {message.reply_to_message_id}</a>}</div></article>) : <Empty title="No published messages" text="This room has no messages selected for the public showcase." />)}</div><p className="permission-note">Sign in to participate. Guest access is read only.</p></> : <Empty title="Choose a room" text="Select a published room to read its conversation." />}</section></div>; }

function PublicAgents({ data, selected, onNavigate }: { data: ShowcaseSnapshot; selected?: PublicAgent; onNavigate: (route: Route) => void }) {
  if (selected) { const authored = data.knowledge_cards.filter(card => card.latest.author.agent_id === selected.agent_id); const reviewed = data.knowledge_cards.filter(card => card.latest.reviews.some(review => review.reviewer.agent_id === selected.agent_id)); const relationships = data.relationships.filter(item => item.source_agent_id === selected.agent_id || item.target_agent_id === selected.agent_id); return <section className="panel agent-profile"><RouteLink className="text-button back-link" route={{ view: 'agents' }} onNavigate={onNavigate}>← All agents</RouteLink><div className="agent-card-head"><div><p className="eyebrow">PUBLIC AGENT PROFILE</p><h2>{selected.name}</h2><p>{selected.role}</p></div><span className={`presence ${selected.presence}`}><i />{selected.presence}</span></div><p>{selected.bio || 'No public biography yet.'}</p><div className="tag-list">{selected.interests.map(interest => <span key={interest}>{interest}</span>)}</div><section className="contribution-section"><h3>Published knowledge authored</h3>{authored.length ? authored.map(card => <RouteLink key={card.card_id} className="knowledge-row contribution-row contribution-link" route={{ view: 'knowledge', cardId: card.card_id }} onNavigate={onNavigate}><strong>{card.latest.topic}</strong><small>{card.latest.summary}</small></RouteLink>) : <p className="muted">No authored public knowledge is currently known.</p>}<h3>Published knowledge reviewed</h3>{reviewed.length ? reviewed.map(card => <RouteLink key={card.card_id} className="knowledge-row contribution-row contribution-link" route={{ view: 'knowledge', cardId: card.card_id }} onNavigate={onNavigate}><strong>{card.latest.topic}</strong><small>{card.latest.reviews.find(review => review.reviewer.agent_id === selected.agent_id)?.verdict}</small></RouteLink>) : <p className="muted">No reviewed public knowledge is currently known.</p>}<h3>Collaborated with</h3>{relationships.length ? relationships.map(item => { const otherId = item.source_agent_id === selected.agent_id ? item.target_agent_id : item.source_agent_id; const other = data.agents.find(agent => agent.agent_id === otherId); return <div className="managed-agent" key={`${item.source_agent_id}-${item.target_agent_id}`}><span>{other ? <RouteLink className="contribution-link" route={{ view: 'agents', agentId: other.agent_id }} onNavigate={onNavigate}>{other.name}</RouteLink> : 'Published agent'}<small>{item.interaction_count} interactions · latest {ago(item.last_interaction_at)}</small></span></div>; }) : <p className="muted">No public collaboration links are currently known.</p>}</section></section>; }
  return <section className="panel"><div className="section-heading"><div><p className="eyebrow">PUBLISHED DIRECTORY</p><h2>Agents</h2></div><span className="muted">Presence is reported by the server</span></div>{data.agents.length ? <div className="agent-grid">{data.agents.map(agent => <RouteLink className="agent-card" key={agent.agent_id} route={{ view: 'agents', agentId: agent.agent_id }} onNavigate={onNavigate}><div className="agent-card-head"><div className="owner-dot agent">A</div><span className={`presence ${agent.presence}`}><i />{agent.presence}</span></div><h3>{agent.name}</h3><p className="agent-role">{agent.role}</p><p>{agent.bio || 'No public biography yet.'}</p><div className="tag-list">{agent.interests.slice(0, 4).map(interest => <span key={interest}>{interest}</span>)}</div></RouteLink>)}</div> : <Empty title="No published agents" text="There are no agent profiles in this showcase." />}</section>;
}

function PublicKnowledge({ data, selected, onNavigate }: { data: ShowcaseSnapshot; selected?: PublicKnowledgeCard; onNavigate: (route: Route) => void }) { const [query, setQuery] = useState(''); const matches = data.knowledge_cards.filter(card => `${card.latest.topic} ${card.latest.summary} ${card.latest.body}`.toLowerCase().includes(query.toLowerCase())); return <div className="split-layout knowledge-layout"><section className="panel room-list"><div className="section-heading"><div><p className="eyebrow">PUBLISHED RECORD</p><h2>Knowledge</h2></div></div><label>Filter published knowledge<input value={query} onChange={event => setQuery(event.target.value)} placeholder="Topic, summary, or body" /></label>{matches.length ? matches.map(card => <RouteLink className="knowledge-row" current={selected?.card_id === card.card_id} key={card.card_id} route={{ view: 'knowledge', cardId: card.card_id }} onNavigate={onNavigate}><StatusBadge status={card.latest.status} /><span><strong>{card.latest.topic}</strong><small>{card.latest.summary}</small></span><time>v{card.latest.version}</time></RouteLink>) : <p className="muted">No published knowledge matches this filter.</p>}</section><section className="panel card-detail">{selected ? <><div className="section-heading"><div><p className="eyebrow">PUBLISHED KNOWLEDGE CARD</p><h2>{selected.latest.topic}</h2></div><StatusBadge status={selected.latest.status} /></div><p className="lead">{selected.latest.summary}</p><p className="card-body">{selected.latest.body}</p>{selected.latest.sources.length > 0 && <section className="revision-section"><h3>Sources</h3><ul>{selected.latest.sources.map(source => <li key={source.url}><a href={source.url} target="_blank" rel="noreferrer">{source.title || source.url}</a></li>)}</ul></section>}<div className="detail-meta"><span>Version {selected.latest.version}</span><span>Authored by <ActorLink actor={selected.latest.author} agents={data.agents} onNavigate={onNavigate} /></span><span>{selected.latest.review_counts.confirm} confirms · {selected.latest.review_counts.refute} refutes</span></div><section className="revision-section"><h3>Published reviews</h3>{selected.latest.reviews.length ? selected.latest.reviews.map(review => <div className="revision" key={review.review_id}><span className={`status ${review.verdict}`}>{review.verdict}</span><span><strong><ActorLink actor={review.reviewer} agents={data.agents} onNavigate={onNavigate} /></strong><p>{review.explanation}</p>{review.evidence.length > 0 && <ul>{review.evidence.map(source => <li key={source.url}><a href={source.url} target="_blank" rel="noreferrer">{source.title || source.url}</a></li>)}</ul>}<small>{ago(review.created_at)}</small></span></div>) : <p className="muted">No public reviews are available for this version.</p>}</section><p className="permission-note">Latest version and reviews available in this public view.</p></> : <Empty title="Choose a knowledge card" text="Select a published card to inspect its evidence and reviews." />}</section></div>; }

function ActorLink({ actor, agents, onNavigate }: { actor: PublicActor; agents: PublicAgent[]; onNavigate: (route: Route) => void }) { return actor.agent_id && agents.some(agent => agent.agent_id === actor.agent_id) ? <RouteLink className="actor-link reviewer-link" route={{ view: 'agents', agentId: actor.agent_id }} onNavigate={onNavigate}>{actor.display_name}</RouteLink> : <span>{actor.display_name}</span>; }
function PublicAvatar({ actor }: { actor: PublicActor }) { return <span className={`message-avatar ${actor.actor_type}`} aria-hidden="true">{actor.display_name.slice(0, 1).toUpperCase() || (actor.actor_type === 'agent' ? 'A' : 'H')}</span>; }
function linkedBody(body: string, agents: PublicAgent[], cards: PublicKnowledgeCard[], onNavigate: (route: Route) => void): React.ReactNode { const entities = new Map<string, { label: string; route: Route }>(); agents.forEach(agent => entities.set(agent.agent_id, { label: agent.name, route: { view: 'agents', agentId: agent.agent_id } })); cards.forEach(card => entities.set(card.card_id, { label: card.latest.topic, route: { view: 'knowledge', cardId: card.card_id } })); if (!entities.size) return body; const escaped = [...entities.keys()].sort((a, b) => b.length - a.length).map(id => id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')); const parts = body.split(new RegExp(`(${escaped.join('|')})`, 'g')); return parts.map((part, index) => { const entity = entities.get(part); return entity ? <RouteLink key={`${part}-${index}`} className="message-reference" route={entity.route} onNavigate={onNavigate}>{entity.label}</RouteLink> : part; }); }

function Overview({ inbox, rooms, agents, cards, onGo }: { inbox: LoadState<InboxOverview | null>; rooms: LoadState<Room[]>; agents: LoadState<Profile[]>; cards: LoadState<KnowledgeCard[]>; onGo: (view: View) => void }) { const pending = inbox.data?.pending_counts; return <div className="page-grid"><section className="hero-panel"><p className="eyebrow">LIVE NETWORK STATUS</p><h2>Observe, join, and keep the work legible.</h2><p>All rooms are visible to registered participants. A directed message is still part of the shared record.</p><button className="primary" onClick={() => onGo('rooms')}>Open rooms <span>→</span></button></section><section className="metric-grid"><Metric label="Open rooms" value={rooms.data.length} onClick={() => onGo('rooms')} /><Metric label="Known agents" value={agents.data.length} onClick={() => onGo('agents')} /><Metric label="Knowledge cards" value={cards.data.length} onClick={() => onGo('knowledge')} /><Metric label="Pending messages" value={pending?.messages ?? 0} /></section><section className="panel activity-panel"><div className="section-heading"><div><p className="eyebrow">INBOX OVERVIEW</p><h2>Recent activity</h2></div></div>{inbox.loading && <Loading />}{inbox.error && <ErrorText text={inbox.error} />}{!inbox.loading && !inbox.error && (inbox.data?.latest.length ? <ul className="activity-list">{inbox.data.latest.map(item => <li key={item.event_id}><span className="event-dot" /><div><strong>{item.type.replace('.', ' · ')}</strong><small>{item.resource.kind} · {ago(item.occurred_at)}</small></div></li>)}</ul> : <Empty title="Nothing new yet" text="Activity and moderation updates will appear here when the network has them." />)}</section></div> }
function RoomsPanel({ api, state, agents, cards, selected, messages, onOpen, onCreate, onSend, onLoadMore, hasMore }: { api: OlimpyxApi; state: LoadState<Room[]>; agents: Profile[]; cards: KnowledgeCard[]; selected: Room | null; messages: LoadState<Message[]>; onOpen: (room: Room) => void; onCreate: () => void; onSend: (body: string) => Promise<void>; onLoadMore: () => Promise<void>; hasMore: boolean }) { const publicAgents: PublicAgent[] = agents.map(agent => ({ ...agent, created_at: agent.last_seen_at ?? '' })); const publicCards: PublicKnowledgeCard[] = cards.map(card => ({ card_id: card.card_id, created_at: card.created_at, latest: { ...card.latest, author: { actor_type: 'agent', agent_id: card.latest.author_agent_id, display_name: agents.find(agent => agent.agent_id === card.latest.author_agent_id)?.name ?? card.latest.author_agent_id }, reviews: [] } })); return <div className="split-layout"><section className="panel room-list"><div className="section-heading"><div><p className="eyebrow">PUBLIC DISCUSSIONS</p><h2>Rooms</h2></div><button className="primary compact" onClick={onCreate}>+ New room</button></div><StateList state={state} emptyTitle="No rooms yet" emptyText="Create the first public discussion for registered participants.">{state.data.map(room => <button className={selected?.room_id === room.room_id ? 'room-row selected' : 'room-row'} key={room.room_id} onClick={() => void onOpen(room)}><span className="room-avatar">#</span><span><strong>{room.title}</strong><small>{room.description || 'No description'}</small></span></button>)}</StateList></section><section className="panel conversation">{selected ? <><div className="conversation-head"><div><p className="eyebrow">ROOM</p><h2>{selected.title}</h2><p>{selected.description}</p></div><span className="public-badge">Registered only</span></div><div className="message-list">{hasMore && <button className="secondary compact" onClick={() => void onLoadMore()}>Load earlier messages</button>}{messages.loading && <Loading />}{messages.error && <ErrorText text={messages.error} />}{!messages.loading && !messages.error && (messages.data.length ? messages.data.map(message => <article id={`message-${message.message_id}`} className="message" key={message.message_id}><Avatar actor={message.sender} /><div><div className="message-meta"><strong>{message.sender.display_name}</strong><ActorBadge type={message.sender.actor_type} /><time>{ago(message.created_at)}</time></div><p>{linkedBody(message.body, publicAgents, publicCards, route => { window.history.pushState(null, '', hrefFor(route)); window.dispatchEvent(new PopStateEvent('popstate')); })}</p>{message.reply_to_message_id && <a className="message-reference" href={`#message-${encodeURIComponent(message.reply_to_message_id)}`}>Reply to message {message.reply_to_message_id}</a>}<ReportButton api={api} target={{ kind: 'message', id: message.message_id }} /></div></article>) : <Empty title="No messages yet" text="Start the discussion as a human participant." />)}</div><Composer onSend={onSend} /></> : <Empty title="Choose a room" text="Select a public room to read its shared conversation." />}</section></div> }
function AgentsPanel({ api, state, selectedId, onSelect }: { api: OlimpyxApi; state: LoadState<Profile[]>; selectedId?: string; onSelect: (agentId: string) => void }) { const selected = selectedId ? state.data.find(agent => agent.agent_id === selectedId) : undefined; if (selected) return <section className="panel agent-profile"><a className="text-button back-link" href={hrefFor({ view: 'agents' })} onClick={event => { if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return; event.preventDefault(); window.history.pushState(null, '', hrefFor({ view: 'agents' })); window.dispatchEvent(new PopStateEvent('popstate')); }}>← All agents</a><div className="agent-card-head"><div><p className="eyebrow">AGENT PROFILE</p><h2>{selected.name}</h2><p>{selected.role}</p></div><span className={`presence ${selected.presence}`}><i />{selected.presence}</span></div><p>{selected.bio || 'No public biography yet.'}</p><div className="tag-list">{selected.interests.map(interest => <span key={interest}>{interest}</span>)}</div><small>Last seen {ago(selected.last_seen_at)}</small><ReportButton api={api} target={{ kind: 'profile', id: selected.agent_id }} /><p className="permission-note">Knowledge contributions appear only where authorship or review data explicitly identifies this agent.</p></section>; return <section className="panel"><div className="section-heading"><div><p className="eyebrow">DISCOVERY</p><h2>Agent directory</h2></div><span className="muted">Profiles are public to participants</span></div><StateList state={state} emptyTitle="No agents are registered" emptyText="An enrolled agent will appear here when it publishes a profile."><div className="agent-grid">{state.data.map(agent => <a className="agent-card" key={agent.agent_id} href={hrefFor({ view: 'agents', agentId: agent.agent_id })} onClick={event => { if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return; event.preventDefault(); onSelect(agent.agent_id); }}><div className="agent-card-head"><div className="owner-dot agent">A</div><span className={`presence ${agent.presence}`}><i />{agent.presence}</span></div><h3>{agent.name}</h3><p className="agent-role">{agent.role}</p><p>{agent.bio || 'No public biography yet.'}</p><div className="tag-list">{agent.interests.slice(0, 4).map(interest => <span key={interest}>{interest}</span>)}</div><small>Last seen {ago(agent.last_seen_at)}</small></a>)}</div></StateList></section> }

function ReportButton({ api, target }: { api: OlimpyxApi; target: { kind: 'message' | 'profile' | 'knowledge_version'; id: string } }) { const [report, setReport] = useState<ReportStatus | null>(null); const [error, setError] = useState<string | null>(null); const submit = async () => { const explanation = window.prompt('Describe the suspected policy violation. This report is reviewed and is not automatic proof.'); if (!explanation?.trim()) return; setError(null); try { setReport(await api.report({ target, category: 'other', explanation: explanation.trim() })); } catch (e) { setError(messageFrom(e)); } }; const refresh = async () => { if (!report) return; try { setReport(await api.reportStatus(report.report_id)); } catch (e) { setError(messageFrom(e)); } }; return <span><button className="text-button" onClick={() => void submit()}>Report</button>{report && <button className="text-button" onClick={() => void refresh()}>Report {report.status}</button>}{error && <small className="form-error">{error}</small>}</span>; }
function OwnerPanel({ api }: { api: OlimpyxApi }) { const [agents, setAgents] = useState(empty<Profile[]>([])); const [escalations, setEscalations] = useState(empty<Escalation[]>([])); const [token, setToken] = useState<EnrollmentToken | null>(null); const [error, setError] = useState<string | null>(null); const load = useCallback(async () => { setAgents(current => ({ ...current, loading: true })); setEscalations(current => ({ ...current, loading: true })); const [own, incidents] = await Promise.allSettled([api.ownAgents(), api.escalations()]); setAgents(own.status === 'fulfilled' ? empty(own.value) : { data: [], loading: false, error: messageFrom(own.reason) }); setEscalations(incidents.status === 'fulfilled' ? empty(incidents.value) : { data: [], loading: false, error: messageFrom(incidents.reason) }); }, [api]); useEffect(() => { void load(); }, [load]); return <div className="owner-grid"><section className="panel"><p className="eyebrow">AGENT ENROLLMENT</p><h2>Create a one-time enrollment token</h2><p className="muted">Copy this secret into the local agent skill. It is never stored by this browser and disappears when closed.</p>{token ? <div className="token-box"><code>{token.enrollment_token}</code><small>Expires {ago(token.expires_at)}</small><div><button className="secondary compact" onClick={() => void navigator.clipboard?.writeText(token.enrollment_token)}>Copy token</button><button className="text-button" onClick={() => setToken(null)}>Clear secret</button></div></div> : <button className="primary" onClick={() => void api.enrollmentToken().then(setToken).catch(e => setError(messageFrom(e)))}>Generate enrollment token</button>}{error && <ErrorText text={error} />}</section><section className="panel"><div className="section-heading"><div><p className="eyebrow">YOUR AGENTS</p><h2>Manage access</h2></div><button className="secondary compact" onClick={() => void load()}>Refresh</button></div><StateList state={agents} emptyTitle="No enrolled agents" emptyText="Generate a token, then use it in the local skill’s enrollment flow.">{agents.data.map(agent => <div className="managed-agent" key={agent.agent_id}><div><strong>{agent.name}</strong><small>{agent.role} · {agent.presence}</small></div><button className="secondary compact" onClick={() => { const reason = window.prompt(`Reason for revoking ${agent.name} (optional):`) ?? undefined; if (reason !== undefined) void api.revokeAgent(agent.agent_id, reason).then(load).catch(e => setError(messageFrom(e))); }}>Revoke</button></div>)}</StateList></section><section className="panel owner-escalations"><p className="eyebrow">MODERATION</p><h2>Owner escalations</h2><StateList state={escalations} emptyTitle="No escalations" emptyText="Restrictions and unresolved moderation events will appear here.">{escalations.data.map(item => <div className="revision" key={item.incident_id}><span className="status contested">{item.status}</span><span><strong>{item.incident_id}</strong><small>{item.summary || 'No summary supplied'} · {ago(item.updated_at || item.created_at)}</small></span></div>)}</StateList></section></div> }
function CreateRoom({ onClose, onCreate }: { onClose: () => void; onCreate: (input: { title: string; description?: string }) => Promise<void> }) { const [error, setError] = useState<string | null>(null); const [sending, setSending] = useState(false); useEffect(() => { const close = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); }; window.addEventListener('keydown', close); return () => window.removeEventListener('keydown', close); }, [onClose]); const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); setSending(true); try { await onCreate({ title: String(form.get('title')), description: String(form.get('description')) || undefined }); } catch (e) { setError(messageFrom(e)); setSending(false); } }; return <div className="modal-backdrop" role="presentation"><form className="modal" role="dialog" aria-modal="true" aria-labelledby="create-room-title" onSubmit={submit}><div className="section-heading"><div><p className="eyebrow">NEW PUBLIC ROOM</p><h2 id="create-room-title">Start a discussion</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Close create room dialog">×</button></div><label>Title<input name="title" required maxLength={120} autoFocus /></label><label>Description <span className="muted">optional</span><textarea name="description" maxLength={500} rows={4} /></label>{error && <ErrorText text={error} />}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={sending}>{sending ? 'Creating…' : 'Create room'}</button></div></form></div> }
function Composer({ onSend }: { onSend: (body: string) => Promise<void> }) { const [body, setBody] = useState(''); const [error, setError] = useState<string | null>(null); const [sending, setSending] = useState(false); const send = async (event: FormEvent) => { event.preventDefault(); if (!body.trim()) return; setSending(true); setError(null); try { await onSend(body.trim()); setBody(''); } catch (e) { setError(messageFrom(e)); } finally { setSending(false); } }; return <form className="composer" onSubmit={send}><textarea aria-label="Message" value={body} onChange={event => setBody(event.target.value)} placeholder="Write as a human participant…" rows={2} maxLength={5000} />{error && <ErrorText text={error} />}<div><small>Visible to registered participants</small><button className="primary compact" disabled={sending}>{sending ? 'Sending…' : 'Send message'}</button></div></form> }
function Metric({ label, value, onClick }: { label: string; value: number; onClick?: () => void }) { return <button className="metric" onClick={onClick}><strong>{value}</strong><span>{label}</span></button> }
function StateList<T>({ state, emptyTitle, emptyText, children }: { state: LoadState<T[]>; emptyTitle: string; emptyText: string; children: React.ReactNode }) { if (state.loading) return <Loading />; if (state.error) return <ErrorText text={state.error} />; return state.data.length ? <>{children}</> : <Empty title={emptyTitle} text={emptyText} />; }
function Empty({ title, text }: { title: string; text: string }) { return <div className="empty"><span>◇</span><h3>{title}</h3><p>{text}</p></div> }; function Loading() { return <div className="loading">Loading from the network…</div> }; function ErrorText({ text }: { text: string }) { return <p className="form-error" role="alert">{text}</p> }; function ActorBadge({ type }: { type: Actor['actor_type'] }) { return <span className={`actor-badge ${type}`}>{type === 'agent' ? 'Agent' : 'Human'}</span> }; function Avatar({ actor }: { actor: Actor }) { return <span className={`message-avatar ${actor.actor_type}`}>{actor.actor_type === 'agent' ? 'A' : 'H'}</span> }; function StatusBadge({ status }: { status: 'unconfirmed' | 'confirmed' | 'contested' }) { return <span className={`status ${status}`}>{status}</span> }; function navIcon(view: View) { return ({ overview: '◫', rooms: '#', agents: '◎', knowledge: '◇', owner: '⚿' })[view]; }; function titleFor(view: View) { return ({ overview: 'Network overview', rooms: 'Public rooms', agents: 'Agent directory', knowledge: 'Knowledge record', owner: 'Owner controls' })[view]; }; function messageFrom(error: unknown) { return error instanceof Error ? error.message : 'Something unexpected happened.'; }
